import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import '../../core/repository.dart';
import 'knowledge_widgets.dart';

class SourceIntelligencePage extends ConsumerWidget{
 const SourceIntelligencePage({super.key,required this.id});final String id;
 @override Widget build(BuildContext context,WidgetRef ref)=>Scaffold(appBar:AppBar(title:const Text('Source Intelligence')),body:ref.watch(sourceIntelligenceProvider(id)).when(loading:knowledgeLoading,error:(e,_)=>knowledgeError(e),data:(s)=>ListView(padding:const EdgeInsets.all(16),children:[
 Text(s['title'] as String,style:Theme.of(context).textTheme.headlineSmall),const Text('Local provenance and retained-state history. A fingerprint is not publisher authentication, and parsing confidence is not source reliability.'),
 Wrap(spacing:8,children:[TextButton(onPressed:()=>context.push('/reader/${Uri.encodeComponent(id)}'),child:const Text('Open original source')),TextButton(onPressed:()=>context.push('/knowledge/map?kind=document&id=${Uri.encodeComponent(id)}'),child:const Text('Explore knowledge map')),TextButton(onPressed:()=>context.push('/knowledge/new?source=${Uri.encodeComponent(id)}'),child:const Text('Record linked decision')),TextButton(onPressed:()=>context.push('/knowledge/compress?source=${Uri.encodeComponent(id)}'),child:const Text('Create optional overview'))]),
 knowledgeField('Recorded original URL',s['source_url']),knowledgeField('Capture method',s['capture_method']),knowledgeField('Captured at',knowledgeTime(s['captured_ts'])),knowledgeField('Recorded author',s['author']),knowledgeField('Recorded language',s['language']),knowledgeField('Parsing heuristic — not publisher quality',s['extraction_confidence']),
 ExpansionTile(title:const Text('Fingerprints — three distinct representations'),children:[knowledgeField('Recorded original-byte SHA-256 reference',s['original_sha256']),knowledgeField('Stored content fingerprint (import record)',s['stored_content_fingerprint']),knowledgeField('Current normalized compiler-block fingerprint',s['current_representation_fingerprint']),const ListTile(title:Text('No original bytes were re-verified by opening this page. Use the explicit Consumer X-Ray integrity check; matching bytes still do not establish publisher authenticity.')),TextButton(onPressed:()=>context.push('/xray/document/${Uri.encodeComponent(id)}'),child:const Text('Open explicit original integrity check'))]),
 ExpansionTile(title:const Text('Dates — explicit kinds only'),children:knowledgeRows(s,'timestamps').map((t)=>ListTile(title:Text('${t['kind']} · ${knowledgeTime(t['ts'])}'),subtitle:Text(t['note'] as String? ??'Recorded date'))).toList()),
 ExpansionTile(title:const Text('Retained-state history (first 200 records)'),initiallyExpanded:true,children:[
 const ListTile(title:Text('Snapshots describe state when recorded, not reconstructed extraction or transformation events. Intermediate raw extraction may not be archived.')),
 if(knowledgeRows(s,'history').isEmpty)const ListTile(title:Text('No retained-state history recorded for this source. Legacy processing details are unavailable.')),
 ...knowledgeRows(s,'history').map((h)=>ExpansionTile(title:Text('${h['stage']} · ${knowledgeTime(h['recorded_ts'])}'),subtitle:Text(h['representation_kind'] as String),children:[knowledgeField('Recorded version',h['version']),knowledgeField('Recorded fingerprint',h['fingerprint']),knowledgeField('Meaning',h['explanation'])])),
 TextButton(onPressed:()async{if(await knowledgeConfirm(context,'Record current retained state?','This records references to current original and normalized-block fingerprints now. It does not reconstruct earlier pipeline events or verify publisher authenticity.')){if(!context.mounted)return;await knowledgeChange(context,ref,(r)=>r.sourceSnapshot(id));}},child:const Text('Record current retained-state snapshot')),
 ]),
 ExpansionTile(title:const Text('Known derived artifacts — not original content'),children:[if(knowledgeRows(s,'artifacts').isEmpty)const ListTile(title:Text('No known derived artifacts recorded.')),...knowledgeRows(s,'artifacts').map((a)=>ListTile(title:Text(a['kind'] as String),subtitle:Text('${a['version']} · ${knowledgeTime(a['recorded_ts'])}\n${a['explanation']}'),onTap:a['kind']=='derived_extractive_compression'?()=>context.push('/knowledge/compression/${a['version']}'):null))]),
 ExpansionTile(title:const Text('User annotations (first 100)'),children:knowledgeRows(s,'annotations').map((a)=>Card(child:Column(children:[knowledgeField('User note',a['note']),knowledgeField('Recorded annotation quote',a['quote']),KnowledgeSourceButtons(id:id,blockIdx:(a['block_idx'] as num?)?.toInt())]))).toList()),
 ExpansionTile(title:const Text('Explicit linked decisions (first 100)'),children:knowledgeStrings(s,'decision_ids').map((decisionId)=>ref.watch(decisionProvider(decisionId)).when(loading:knowledgeLoading,error:(e,_)=>knowledgeError(e),data:(d)=>ListTile(title:Text(d.title),subtitle:Text(d.archived?'User-recorded · archived':'User-recorded'),onTap:()=>context.push('/knowledge/decision/$decisionId')))).toList()),
 ExpansionTile(title:const Text('Separately archived version candidates'),children:[const ListTile(title:Text('Exact saved URL or stored version/follow-up link only. No live page fetch, monitoring or silent replacement.')),...knowledgeRows(s,'versions').map((v)=>Card(child:Column(children:[ListTile(title:Text(v['title'] as String),subtitle:Text('Captured ${knowledgeTime(v['captured_ts'])}\n${v['basis']}')),KnowledgeSourceButtons(id:v['item_id'] as String),TextButton(onPressed:()=>context.push('/knowledge/diff?before=${Uri.encodeComponent(v['item_id'] as String)}&after=${Uri.encodeComponent(id)}'),child:const Text('Compare saved text (candidate → this source)'))])))]),knowledgeLimits(s),
 ])));
}
class SourceDiffPage extends ConsumerWidget{
 const SourceDiffPage({super.key,required this.beforeId,required this.afterId});final String beforeId,afterId;
 @override Widget build(BuildContext context,WidgetRef ref)=>Scaffold(appBar:AppBar(title:const Text('Archived text comparison')),body:ref.watch(sourceDiffProvider(jsonEncode({'before_id':beforeId,'after_id':afterId}))).when(loading:knowledgeLoading,error:(e,_)=>knowledgeError(e),data:(d)=>ListView(padding:const EdgeInsets.all(16),children:[
 const Text('Comparison direction is explicit, not a claim about publisher version order. These are separately saved local sources; originals remain unchanged.'),knowledgeField('Before source',beforeId),KnowledgeSourceButtons(id:beforeId),knowledgeField('After source',afterId),KnowledgeSourceButtons(id:afterId),Text('Exact same recorded URL: ${d['same_saved_url']} · same stored content fingerprint: ${d['same_recorded_content_fingerprint']}'),if(d['limited']==true)const ListTile(leading:Icon(Icons.warning_amber),title:Text('Diff truncated by safety limits.')),
 const ListTile(title:Text('Lines only in the before source')),...knowledgeRows(d,'removed').map(knowledgeQuote),const ListTile(title:Text('Lines only in the after source')),...knowledgeRows(d,'added').map(knowledgeQuote),if(knowledgeRows(d,'removed').isEmpty&&knowledgeRows(d,'added').isEmpty)const ListTile(title:Text('No line-presence changes found. Reordering and duplicate counts are not compared.')),Text(d['explanation'] as String),
 ])));
}
